-- Readable IDs for every table (CLAUDE.md, "IDs"): PREFIX-NNN, a 3-letter
-- prefix per table and a number zero-padded to 3 digits (VEN-053), growing past
-- 999 (VEN-1000). Generated by the database, so every insert gets one —
-- application code, nested and bulk creates, upserts, seeds, scripts, tests
-- and raw SQL alike — and nothing can bypass it.
--
-- Safe on a database whose rows already use readable IDs (such as VEN-053 on
-- the shared database): each counter starts from the highest number already
-- in its table, so no ID is ever issued twice. Rows still holding a cuid are
-- converted, oldest first; every foreign key is ON UPDATE CASCADE, so the
-- references follow. RevokedToken rows are deleted instead: they only record
-- logged-out tokens, and RevokedToken.userId is not a foreign key.
--
-- Converting User IDs ends existing sessions: a login token carries the old
-- user ID, so everyone logs in again.

-- 1. The generator: the next ID for a prefix, from its IdCounter row, in one
--    atomic statement — concurrent inserts never get the same number, and a
--    rolled-back transaction gives its number back.
CREATE OR REPLACE FUNCTION next_readable_id(p_prefix TEXT) RETURNS TEXT
LANGUAGE sql VOLATILE AS $$
  INSERT INTO "IdCounter" ("prefix", "last") VALUES (p_prefix, 1)
  ON CONFLICT ("prefix") DO UPDATE SET "last" = "IdCounter"."last" + 1
  RETURNING p_prefix || '-' || CASE WHEN "last" < 1000 THEN lpad("last"::text, 3, '0') ELSE "last"::text END;
$$;

-- 2. Logged-out tokens: deleted rather than converted.
DELETE FROM "RevokedToken";

-- 3-5. Per table: start the counter after the highest readable ID already
-- there, convert the remaining cuid rows (oldest first), then make the
-- generator the column's default and keep the format with a CHECK.
DO $do$
DECLARE
  t RECORD;
  r RECORD;
  highest INTEGER;
BEGIN
  FOR t IN SELECT * FROM (VALUES
    ('User', 'USR', $o$"createdAt"$o$),
    ('EventRequest', 'EVT', $o$"createdAt"$o$),
    ('Venue', 'VEN', $o$"createdAt"$o$),
    ('VenueBooking', 'BKG', $o$"createdAt"$o$),
    ('BookingDecision', 'BDC', $o$"createdAt"$o$),
    ('VenueBlock', 'BLK', $o$"createdAt"$o$),
    ('Equipment', 'EQP', $o$"createdAt"$o$),
    ('EquipmentReservation', 'RSV', $o$"createdAt"$o$),
    ('EquipmentRequirement', 'REQ', $o$"createdAt"$o$),
    ('EventChange', 'CHG', $o$"createdAt"$o$),
    ('EventChangeRequest', 'CRQ', $o$"createdAt"$o$),
    ('EventChangeRequestEquipment', 'CRE', NULL),
    ('Registration', 'REG', $o$"createdAt"$o$),
    ('Notification', 'NTF', $o$"createdAt"$o$),
    ('BookingSuggestion', 'BSG', $o$"createdAt"$o$),
    ('EquipmentStatusChange', 'ESC', $o$"changedAt"$o$),
    ('RevokedToken', 'RVT', $o$"createdAt"$o$),
    ('ClarificationMessage', 'CLM', $o$"createdAt"$o$),
    ('SafetyReview', 'SFR', $o$"createdAt"$o$)
  ) AS v(tbl, prefix, order_col)
  LOOP
    EXECUTE format(
      'SELECT max(substring(id FROM %L)::int) FROM %I WHERE id ~ %L',
      '^' || t.prefix || '-([0-9]+)$', t.tbl, '^' || t.prefix || '-[0-9]+$'
    ) INTO highest;

    IF highest IS NOT NULL THEN
      INSERT INTO "IdCounter" ("prefix", "last") VALUES (t.prefix, highest)
      ON CONFLICT ("prefix") DO UPDATE SET "last" = GREATEST("IdCounter"."last", EXCLUDED."last");
    END IF;

    FOR r IN EXECUTE format(
      'SELECT id FROM %I WHERE id !~ %L ORDER BY %s id',
      t.tbl, '^' || t.prefix || '-[0-9]+$',
      CASE WHEN t.order_col IS NULL THEN '' ELSE t.order_col || ', ' END
    )
    LOOP
      EXECUTE format('UPDATE %I SET id = next_readable_id(%L) WHERE id = %L', t.tbl, t.prefix, r.id);
    END LOOP;

    EXECUTE format('ALTER TABLE %I ALTER COLUMN id SET DEFAULT next_readable_id(%L::text)', t.tbl, t.prefix);

    -- BookingSuggestion and EquipmentStatusChange already have their check.
    IF t.tbl NOT IN ('BookingSuggestion', 'EquipmentStatusChange') THEN
      EXECUTE format(
        'ALTER TABLE %I ADD CONSTRAINT %I CHECK (id ~ %L)',
        t.tbl, t.tbl || '_readable_id', '^' || t.prefix || '-[0-9]{3,}$'
      );
    END IF;
  END LOOP;
END
$do$;
